<?php require '_guard.php';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$s=$pdo->prepare("SELECT r.registration_id,p.status ps FROM registrations r LEFT JOIN payments p ON p.registration_id=r.registration_id WHERE r.registration_id=?");$s->execute([$id]);$r=$s->fetch();if($r&&$action==='confirm'&&in_array($r['ps'],['verified','not_required'],true)){$pdo->prepare("UPDATE registrations SET status='confirmed' WHERE registration_id=?")->execute([$id]);flash('success','Registration confirmed.');}elseif($r&&$action==='reject'){$pdo->prepare("UPDATE registrations SET status='rejected' WHERE registration_id=?")->execute([$id]);flash('warning','Registration rejected.');}else flash('danger','Verify payment first before confirming a paid entry.');go('registrations.php');}$rows=$pdo->query("SELECT r.*,t.name tn,p.status ps,p.amount FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id LEFT JOIN payments p ON p.registration_id=r.registration_id ORDER BY r.created_at DESC")->fetchAll();$pageTitle='Registrations';require '../includes/header.php';?><section class="page-hero compact"><div class="eyebrow">ADMIN / ENTRY OPERATIONS</div><h1>MANAGE <span>ENTRIES.</span></h1></section><?php require 'nav.php';?><section class="box section"><div class="table-responsive"><table class="table arena-table"><thead><tr><th>TEAM / CODE</th><th>TOURNAMENT</th><th>PAYMENT</th><th>ENTRY STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['team_name'])?></b><small><?=e($r['registration_code'])?></small></td><td><?=e($r['tn'])?></td><td><?=e(str_replace('_',' ',$r['ps']??'unpaid'))?> · ₹<?=number_format((float)$r['amount'])?></td><td><?=e(str_replace('_',' ',$r['status']))?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$r['registration_id']?>"><button name="action" value="confirm" class="btn btn-sm btn-success" <?=!in_array($r['ps'],['verified','not_required'],true)?'disabled':''?>>Confirm</button> <button name="action" value="reject" class="btn btn-sm btn-outline-danger">Reject</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
